type rolloutFixture struct {
	t             *testing.T
	now           time.Time
	journal       []byte
	statuses      map[string]Status
	previous      map[string]string
	drained       map[string]bool
	healthError   map[string]error
	returnError   map[string]error
	actionError   map[string]string
	effects       []string
	commands      []Command
	nodes         []string
	confirmClears bool
	deferActions  bool
	loseReply     string
}

func rolloutTarget(version string) Target {
	target := Target{Pin: client.Pin{Version: version}, Enrollment: netbird.Config{ManagementURL: netbird.DefaultManagementURL,
		Region: netbird.DefaultRegion, SetupKeySecretID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.aaaaaaaa.testsecret",
		PeerNames: map[string]string{"10.251.0.11": "gru-1-ctl-1", "10.251.0.12": "gru-1-ctl-2", "10.251.0.13": "gru-1-ctl-3"}}}
	archive := func(arch string) client.Archive {
		return client.Archive{URL: fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", version, version, arch),
			Bytes: 100, SHA256: strings.Repeat("a", 64), BinarySHA256: strings.Repeat("b", 64)}
	}
	target.Pin.Archives.Arm64, target.Pin.Archives.AMD64 = archive("arm64"), archive("amd64")
	return target
}

func newRolloutFixture(t *testing.T) *rolloutFixture {
	t.Helper()
	f := &rolloutFixture{t: t, now: time.Date(2026, 10, 7, 12, 0, 0, 0, time.UTC),
		statuses: map[string]Status{}, previous: map[string]string{}, drained: map[string]bool{},
		healthError: map[string]error{}, returnError: map[string]error{}, actionError: map[string]string{}, nodes: []string{"gru-1-ctl-1", "gru-1-ctl-2", "gru-1-ctl-3"}}
	for i, node := range f.nodes {
		f.statuses[node] = Status{Version: "0.79.0", Connected: true, IP: fmt.Sprintf("100.87.0.%d", i+1), DNS: node + ".nb.ts.internal"}
		f.previous[node] = "0.79.0"
	}
	return f
}

func (f *rolloutFixture) record() Record {
	f.t.Helper()
	var record Record
	if len(f.journal) != 0 {
		if err := json.Unmarshal(f.journal, &record, json.RejectUnknownMembers(true)); err != nil {
			f.t.Fatal(err)
		}
	}
	return record
}

// Every tick gets a fresh reconciler. Only serialized journal bytes and node
// observations survive, as they do when another controller becomes leader.
func (f *rolloutFixture) reconciler() *Reconciler {
	return &Reconciler{
		Now:  func() time.Time { return f.now },
		Load: func(context.Context) (Record, error) { return f.record(), nil },
		Save: func(_ context.Context, record Record) error {
			wire, err := json.Marshal(record)
			if err == nil {
				f.journal = wire
			}
			return err
		},
		Status: func(_ context.Context, node string) (Status, error) {
			status := f.statuses[node]
			status.ObservedAt = f.now
			return status, nil
		},
		Preflight: func(_ context.Context, node string) error {
			f.effects = append(f.effects, "preflight:"+node)
			return nil
		},
		Drain: func(_ context.Context, node string) error {
			for other, drained := range f.drained {
				if drained && other != node {
					f.t.Fatalf("drained %s while %s is still drained", node, other)
				}
			}
			f.drained[node] = true
			f.effects = append(f.effects, "drain:"+node)
			return nil
		},
		Healthy: func(_ context.Context, node string, status Status, _ time.Time) error {
			if err := f.healthError[node]; err != nil {
				return err
			}
			if !status.Connected || status.IP == "" || status.DNS == "" {
				return errors.New("mesh and application probes failed")
			}
			return nil
		},
		Return: func(_ context.Context, node string) error {
			// Restored absence needs ordinary role/LB return checks, not mesh.
			if !f.statuses[node].Missing && (f.healthError[node] != nil || !f.statuses[node].Connected) {
				f.t.Fatalf("returned unhealthy node %s", node)
			}
			f.drained[node] = false
			f.effects = append(f.effects, "return:"+node)
			return f.returnError[node]
		},
		Send: func(_ context.Context, node string, command Command) error {
			if !f.drained[node] {
				f.t.Fatalf("sent %s to serving node %s without a drain", command.Action, node)
			}
			record := f.record()
			if !entityid.Valid(record.ID) || !entityid.Valid(command.ID) || command.ID != CommandID(record.ID, command.Action) {
				f.t.Fatalf("invalid transaction/command identity: %+v %+v", record, command)
			}
			if record.Node != node || record.ID != command.Transaction || !reflect.DeepEqual(record.Target, command.Target) {
				f.t.Fatalf("effect did not use persisted transaction: %#v %#v", record, command)
			}
			f.commands = append(f.commands, command)
			f.effects = append(f.effects, command.Action+":"+node)
			if !f.deferActions {
				f.apply(node, command)
			}
			if f.loseReply == command.Action {
				f.loseReply = ""
				return errors.New("controller lost the worker response")
			}
			return nil
		},
	}
}

func (f *rolloutFixture) apply(node string, command Command) {
	status := f.statuses[node]
	status.ActionID, status.Error = command.ID, f.actionError[command.Action]
	switch command.Action {
	case "install":
		status.Version, status.Pending = command.Target.Pin.Version, command.Transaction
		status.Missing = false
	case "confirm":
		if status.Error == "" || f.confirmClears {
			status.Pending = ""
		}
		if status.Error == "" {
			status.AppliedTargetHash = Hash(command.Target)
		}
	case "rollback":
		if status.Error == "" {
			status.Version, status.Pending, status.AppliedTargetHash = f.previous[node], "", ""
			status.Missing = status.Version == ""
			if status.Missing {
				status.Connected, status.IP, status.DNS = false, "", ""
			}
		}
	}
	f.statuses[node] = status
}

func (f *rolloutFixture) tick(target Target) error {
	return f.reconciler().Tick(f.t.Context(), target, f.nodes)
}

func (f *rolloutFixture) advance(target Target, phase string) {
	f.t.Helper()
	for range 24 {
		if f.record().Phase == phase {
			return
		}
		if err := f.tick(target); err != nil {
			f.t.Fatalf("advance to %s failed in %s: %v", phase, f.record().Phase, err)
		}
	}
	f.t.Fatalf("did not reach %s; record=%#v effects=%v", phase, f.record(), f.effects)
}

func returnPhaseFixture(t *testing.T, phase string) (*rolloutFixture, Target) {
	t.Helper()
	f := newRolloutFixture(t)
	target := rolloutTarget("0.80.0")
	if phase == "return" {
		f.advance(target, phase)
	} else {
		f.advance(target, "install")
		f.now = f.record().Deadline.Add(time.Second)
		f.advance(target, phase)
	}
	return f, target
}

type Target struct {
	Pin        client.Pin     `json:"pin"`
	Enrollment netbird.Config `json:"enrollment"`
}

type Status struct {
	Version           string    `json:"version"`
	AppliedTargetHash string    `json:"applied_target_hash,omitempty"`
	Missing           bool      `json:"missing,omitempty"`
	Connected         bool      `json:"connected"`
	IP                string    `json:"ip,omitempty"`
	DNS               string    `json:"dns,omitempty"`
	Pending           string    `json:"pending,omitempty"`
	ActionID          string    `json:"action_id,omitempty"`
	Error             string    `json:"error,omitempty"`
	ObservedAt        time.Time `json:"observed_at"`
}

func (status Status) Validate() error {
	if status.Pending != "" && !entityid.Valid(status.Pending) || status.ActionID != "" && !entityid.Valid(status.ActionID) {
		return errors.New("invalid NetBird status identity")
	}
	return nil
}

type Command struct {
	Generation  uint64 `json:"generation"`
	ID          string `json:"id"`
	Transaction string `json:"transaction"`
	Action      string `json:"action"`
	Target      Target `json:"target"`
}

// CommandID gives retries of one action the same independently scoped ID.
func CommandID(transaction, action string) string {
	return entityid.Derive("netbird-command", transaction, action)
}

type Record struct {
	ID                string    `json:"id"`
	Node              string    `json:"node"`
	Previous          string    `json:"previous"`
	Target            Target    `json:"target"`
	PinHash           string    `json:"pin_hash"`
	Phase             string    `json:"phase"`
	RollbackRequired  *bool     `json:"rollback_required,omitempty"`
	RecoveryComplete  bool      `json:"recovery_complete,omitempty"`
	RecoveryReturning bool      `json:"recovery_returning,omitempty"`
	Deadline          time.Time `json:"deadline"`
	StartedAt         time.Time `json:"started_at"`
	Reason            string    `json:"reason,omitempty"`
	// Admission survives pin, grant and fence amendments until recovery.
	Fence      jsontext.Value `json:"fence,omitempty"`
	OCIAddress string         `json:"oci_address,omitempty"`
}

// The store and every effect must be guarded by the same authority epoch.
// A failed rollback holds the cell until an operator repairs its access path.
type Reconciler struct {
	Load      func(context.Context) (Record, error)
	Save      func(context.Context, Record) error
	Status    func(context.Context, string) (Status, error)
	Preflight func(context.Context, string) error
	Drain     func(context.Context, string) error
	Healthy   func(context.Context, string, Status, time.Time) error
	Return    func(context.Context, string) error
	Send      func(context.Context, string, Command) error
	Now       func() time.Time
}

func Hash(target Target) string {
	wire, _ := json.Marshal(target, json.Deterministic(true))
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

func CompareVersions(a, b string) (int, error) {
	parse := func(s string) ([3]uint64, error) {
		var out [3]uint64
		parts := strings.Split(strings.TrimPrefix(strings.TrimSpace(s), "v"), ".")
		if len(parts) != 3 {
			return out, errors.New("NetBird version must have three numeric components")
		}
		for i, part := range parts {
			value, err := strconv.ParseUint(part, 10, 32)
			if err != nil || part == "" || len(part) > 1 && part[0] == '0' {
				return out, errors.New("invalid NetBird version")
			}
			out[i] = value
		}
		return out, nil
	}
	x, err := parse(a)
	if err != nil {
		return 0, err
	}
	y, err := parse(b)
	if err != nil {
		return 0, err
	}
	for i := range x {
		if x[i] < y[i] {
			return -1, nil
		}
		if x[i] > y[i] {
			return 1, nil
		}
	}
	return 0, nil
}

func (r *Reconciler) Tick(ctx context.Context, target Target, nodes []string) error {
	currentTime := func() time.Time {
		if r.Now != nil {
			return r.Now().UTC()
		}
		return time.Now().UTC()
	}
	now := currentTime()
	record, err := r.Load(ctx)
	if err != nil {
		return err
	}
	if record.Phase != "" && !entityid.Valid(record.ID) {
		return errors.New("invalid NetBird rollout identity")
	}
	if record.RecoveryReturning && !record.RecoveryComplete {
		// Fence an interrupted return before any status or health gate.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.RecoveryReturning = false
		if err := r.Save(ctx, record); err != nil {
			return err
		}
	}
	returnNode := func() error {
		record.RecoveryReturning = true
		if err := r.Save(ctx, record); err != nil {
			return err
		}
		if err := r.Return(ctx, record.Node); err != nil {
			// Return may clear backend flags before its health check fails.
			if drainErr := r.Drain(ctx, record.Node); drainErr != nil {
				return errors.Join(err, drainErr)
			}
			record.RecoveryReturning = false
			return errors.Join(err, r.Save(ctx, record))
		}
		record.RecoveryReturning = false
		return nil
	}
	rollbackAcknowledged := func(status Status) bool {
		return status.ActionID == CommandID(record.ID, "rollback") && status.Error == "" && status.Version == record.Previous && status.Pending == ""
	}
	recovered := func(status Status, since time.Time) error {
		if record.Previous == "" {
			// First-install rollback restores absence, so mesh probes cannot run.
			if !status.Missing || status.Version != "" || status.ObservedAt.IsZero() ||
				now.Sub(status.ObservedAt) > 15*time.Second || status.ObservedAt.Sub(now) > 2*time.Second {
				return errors.New("previous NetBird absence has not been freshly observed")
			}
			return nil
		}
		return r.Healthy(ctx, record.Node, status, since)
	}
	hash := Hash(target)
	if record.Phase == "failed" {
		// Recover the held node even when this pin stays failed or is removed.
		// The completion marker is written only after our fence is released.
		if !record.RecoveryComplete {
			status, err := r.Status(ctx, record.Node)
			// Older journals lack the marker. Require proof of recovery unless
			// this controller explicitly recorded that no agent mutation began.
			if err != nil || status.Pending != "" || status.Error != "" || (record.RollbackRequired == nil || *record.RollbackRequired) && !rollbackAcknowledged(status) {
				return errors.New("previous NetBird rollback is unresolved")
			}
			if err := recovered(status, time.Time{}); err != nil {
				return err
			}
			if err := returnNode(); err != nil {
				return err
			}
			record.RecoveryComplete = true
			if err := r.Save(ctx, record); err != nil {
				return err
			}
		}
		if record.PinHash == hash {
			return fmt.Errorf("NetBird rollout held on %s: %s", record.Node, record.Reason)
		}
	}
	if record.Phase == "" || record.Phase == "done" || record.Phase == "failed" {
		statuses := make(map[string]Status, len(nodes))
		for _, node := range nodes {
			status, err := r.Status(ctx, node)
			if err != nil {
				return err
			}
			if status.Pending != "" || status.Error != "" {
				return fmt.Errorf("NetBird transaction still pending on %s", node)
			}
			statuses[node] = status
		}
		for _, node := range nodes {
			status := statuses[node]
			if status.Version != "" {
				comparison, err := CompareVersions(status.Version, target.Pin.Version)
				if err != nil {
					return err
				}
				if comparison == 0 && status.AppliedTargetHash == hash {
					continue
				}
			}
			if err := r.Preflight(ctx, node); err != nil {
				return err
			}
			record = Record{ID: entityid.New(), Node: node, Previous: status.Version,
				Target: target, PinHash: hash, Phase: "drain", StartedAt: now, Deadline: now.Add(10 * time.Minute)}
			return r.Save(ctx, record)
		}
		return nil
	}
	transition := func(phase string) error { record.Phase = phase; return r.Save(ctx, record) }
	command := func(action string) error {
		return r.Send(ctx, record.Node, Command{ID: CommandID(record.ID, action), Generation: uint64(record.StartedAt.UnixNano()), Transaction: record.ID, Action: action, Target: record.Target})
	}
	rollback := func(reason string) error {
		record.RollbackRequired = new(true)
		record.Reason = reason
		record.Deadline = now.Add(6 * time.Minute)
		return transition("rollback")
	}
	switch record.Phase {
	case "drain":
		if now.After(record.Deadline) {
			record.RollbackRequired = new(false)
			record.Reason = "drain timed out"
			return transition("failed")
		}
		if err := r.Preflight(ctx, record.Node); err != nil {
			return err
		}
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.Deadline = currentTime().Add(3 * time.Minute)
		return transition("install")
	case "install":
		if now.After(record.Deadline) {
			return rollback("agent did not acknowledge installation")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "install") {
			if status.Error != "" {
				return rollback(status.Error)
			}
			record.Deadline = now.Add(2 * time.Minute)
			return transition("check")
		}
		return command("install")
	case "check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && status.Version == record.Target.Pin.Version && status.Pending == record.ID {
			err = r.Healthy(ctx, record.Node, status, record.StartedAt)
			if err == nil {
				record.Deadline = currentTime().Add(2 * time.Minute)
				return transition("confirm")
			}
		}
		if now.After(record.Deadline) {
			return rollback("new NetBird agent failed mesh health checks")
		}
		return err
	case "confirm":
		if now.After(record.Deadline) {
			return rollback("new NetBird agent was not confirmed")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "confirm") && status.Error == "" && status.Pending == "" && status.Version == record.Target.Pin.Version && status.AppliedTargetHash == record.PinHash {
			record.Deadline = now.Add(2 * time.Minute)
			return transition("return")
		}
		return command("confirm")
	case "return":
		failedReturn := func(err error) error {
			if now.After(record.Deadline) {
				return rollback("confirmed NetBird agent failed return health checks")
			}
			return err
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return failedReturn(err)
		}
		if status.Pending != "" || status.Version != record.Target.Pin.Version || status.AppliedTargetHash != record.PinHash || status.ActionID != CommandID(record.ID, "confirm") || status.Error != "" {
			return failedReturn(errors.New("confirmed NetBird transaction changed before return"))
		}
		if err := r.Healthy(ctx, record.Node, status, record.StartedAt); err != nil {
			return failedReturn(err)
		}
		if err := returnNode(); err != nil {
			return failedReturn(err)
		}
		return transition("done")
	case "rollback":
		// Return may have put backends online before an LB health check
		// failed. Re-establish the same fence before restarting the old agent.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		if err := command("rollback"); err != nil {
			return err
		}
		// Safe re-draining can wait for repaired quorum across many ticks.
		// Allow a full acknowledgment window once the command is sent.
		record.Deadline = currentTime().Add(6 * time.Minute)
		return transition("rollback-check")
	case "rollback-check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && rollbackAcknowledged(status) && recovered(status, record.StartedAt) == nil {
			if err := returnNode(); err != nil {
				if record.RecoveryReturning {
					return err
				}
				if now.After(record.Deadline) {
					record.Reason += "; previous binary failed return health checks (node remains drained)"
					return transition("failed")
				}
				return err
			}
			record.RecoveryComplete = true
			return transition("failed")
		}
		if now.After(record.Deadline) {
			if err := r.Drain(ctx, record.Node); err != nil {
				return err
			}
			record.Reason += "; previous binary did not recover (node remains drained)"
			return transition("failed")
		}
		return command("rollback")
	default:
		return errors.New("unknown NetBird rollout phase")
	}
}

var (
	entropy = ulid.Monotonic(rand.Reader, 0)
	mu      sync.Mutex
)

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func rolloutTarget(version string) Target {
	target := Target{Pin: client.Pin{Version: version}, Enrollment: netbird.Config{ManagementURL: netbird.DefaultManagementURL,
		Region: netbird.DefaultRegion, SetupKeySecretID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.aaaaaaaa.testsecret",
		PeerNames: map[string]string{"10.251.0.11": "gru-1-ctl-1", "10.251.0.12": "gru-1-ctl-2", "10.251.0.13": "gru-1-ctl-3"}}}
	archive := func(arch string) client.Archive {
		return client.Archive{URL: fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", version, version, arch),
			Bytes: 100, SHA256: strings.Repeat("a", 64), BinarySHA256: strings.Repeat("b", 64)}
	}
	target.Pin.Archives.Arm64, target.Pin.Archives.AMD64 = archive("arm64"), archive("amd64")
	return target
}

func Hash(target Target) string {
	wire, _ := json.Marshal(target, json.Deterministic(true))
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

type contextProviderDispatcher func(*http.Request) (*http.Response, error)

func (d contextProviderDispatcher) Do(request *http.Request) (*http.Response, error) {
	return d(request)
}

type instancePrincipalContextDispatcher struct {
	ctx        context.Context
	dispatcher common.HTTPRequestDispatcher
}

func (d instancePrincipalContextDispatcher) Do(request *http.Request) (*http.Response, error) {
	return d.dispatcher.Do(request.WithContext(d.ctx))
}

// SDK credential retries sleep without context checks. Initialization is
// read-only, so cancellation can release the caller while its backoff finishes.
func initializeSecretsClient(ctx context.Context, initialize func() (secrets.SecretsClient, error)) (secrets.SecretsClient, error) {
	if err := ctx.Err(); err != nil {
		return secrets.SecretsClient{}, err
	}
	type result struct {
		client secrets.SecretsClient
		err    error
	}
	done := make(chan result, 1)
	go func() {
		client, err := initialize()
		done <- result{client, err}
	}()
	select {
	case <-ctx.Done():
		return secrets.SecretsClient{}, ctx.Err()
	case initialized := <-done:
		return initialized.client, initialized.err
	}
}

// Admin PAT bounds. NetBird issues "nbp_" + a 30-character secret + a
// 6-character base62 checksum (40 bytes); longer future tokens are accepted
// up to maxAdminPATBytes.
const (
	minAdminPATBytes = 40
	maxAdminPATBytes = 256
)

// validAdminPAT is the single NetBird personal access token shape check: the
// "nbp_" prefix followed by a bounded base62 body.
func validAdminPAT(token []byte) bool {
	if len(token) < minAdminPATBytes || len(token) > maxAdminPATBytes || !bytes.HasPrefix(token, []byte("nbp_")) {
		return false
	}
	for _, c := range token[4:] {
		if !('a' <= c && c <= 'z' || 'A' <= c && c <= 'Z' || '0' <= c && c <= '9') {
			return false
		}
	}
	return true
}

// ValidAdminPAT reports whether token has NetBird's PAT shape. The manager
// client and the OCI Vault reader share this predicate.
func ValidAdminPAT(token []byte) bool { return validAdminPAT(token) }
